      "prompt": {
        "options": [
          {
            "id": "o9f185d70",
            "lang": "vi",
            "text": "Nhàm chán có chức năng hữu ích, nên ta không cần vội lấp đầy mọi khoảng trống"
          },
          {
            "id": "o51aab547",
            "lang": "vi",
            "text": "Mọi công việc tẻ nhạt đều làm tăng năng suất lao động"
