            "text": "Bác sĩ nói chung kém chính xác hơn người dự báo thời tiết"
          },
          {
            "id": "o568a9c98",
            "lang": "vi",
            "text": "Chẩn đoán hình ảnh là lĩnh vực quá khó để thành thạo"
          },
          {
            "id": "oe37c70c1",
            "lang": "vi",
            "text": "Càng nhiều năm kinh nghiệm thì càng trở thành chuyên gia"
